#!/usr/bin/env python3
"""Generate lean/Arche/Anchors.lean: one `#check @Name` per anchor.

`lake build` then fails on the first anchor that doesn't exist in the pinned
Mathlib, with the node id in a comment beside it. Lean is the authority on what
exists; this script only collects names.

Usage: python3 tools/gen_anchor_check.py [--check]   (--check: exit 1 if the file is stale)
"""
from __future__ import annotations

import sys

import mmgraph as G

OUT = G.ROOT / "lean" / "Arche" / "Anchors.lean"


def render(g: G.Graph) -> str:
    lines = [
        "/-",
        "Generated by tools/gen_anchor_check.py. Do not edit by hand.",
        "Every anchor in graph/nodes must elaborate here against the pinned Mathlib.",
        "-/",
        "import Mathlib",
        "",
    ]
    by_decl: dict[str, list[str]] = {}
    for nid in sorted(g.nodes):
        for a in g.nodes[nid].get("anchors", []) or []:
            if a.get("library", "mathlib") in ("mathlib", "lean-core"):
                by_decl.setdefault(a["decl"], []).append(nid)
    for decl in sorted(by_decl):
        lines.append(f"#check @{decl}  -- {', '.join(by_decl[decl])}")
    lines.append("")
    return "\n".join(lines)


def main():
    g = G.load()
    text = render(g)
    if "--check" in sys.argv:
        current = OUT.read_text(encoding="utf-8") if OUT.exists() else ""
        if current != text:
            sys.exit("lean/Arche/Anchors.lean is stale: run python3 tools/gen_anchor_check.py")
        return
    OUT.write_text(text, encoding="utf-8")
    n = text.count("#check")
    print(f"wrote {OUT.relative_to(G.ROOT)} ({n} declarations)")


if __name__ == "__main__":
    main()
